/* IGDC OSO/Auth0 storage listener v2.0.0 */
(function(){
  'use strict';
  if (window.__osauth_listener_installed__) return;
  window.__osauth_listener_installed__ = true;

  var KEYS = ['osauth.tokens.v2','osauth.tokens.v1','igdc.tokens','igdc_auth_tokens','auth0_tokens','auth0spa'];

  function parse(value){ try { return JSON.parse(value); } catch (e) { return null; } }
  function tokenRecord(){
    var stores=[];
    try{stores.push(localStorage);}catch(e){}
    try{stores.push(sessionStorage);}catch(e){}
    for(var s=0;s<stores.length;s++){
      for(var i=0;i<KEYS.length;i++){
        try{
          var data=parse(stores[s].getItem(KEYS[i])||'');
          if(data && (data.id_token || data.idToken || data.__raw || data.raw)) return data;
        }catch(e){}
      }
    }
    return null;
  }
  function tokenPresent(){ return !!tokenRecord(); }
  function notify(type){
    try{ document.dispatchEvent(new CustomEvent('igdc:auth-storage-ready',{detail:{type:type||'ready',tokens:tokenRecord(),present:tokenPresent()}})); }catch(e){}
  }
  function handleMessage(event){
    try{
      if(event.origin !== window.location.origin) return;
      var data=event.data || {};
      if(!data || typeof data !== 'object' || !/^osauth:/.test(data.type||'')) return;
      if(data.type === 'osauth:error'){
        try{ console.warn('[OSAUTH] error:',data.error || 'Unknown authentication error'); }catch(e){}
        notify('error');
        return;
      }
      if(data.type === 'osauth:code' || data.type === 'osauth:done'){
        window.setTimeout(function(){ notify(data.type); },0);
      }
    }catch(e){}
  }
  window.addEventListener('message',handleMessage,false);
  document.addEventListener('osauth:ready',function(){ notify('osauth:ready'); });
  document.addEventListener('osauth:done',function(){ notify('osauth:done'); },true);
  window.addEventListener('pageshow',function(){ notify('pageshow'); });
  notify('boot');
})();
